fn:
// 型男研究所上課當天 21:10：自動用官方 LINE 傳「課後福利社」專屬預約連結給當天的學員（學員密碼已帶入）
function coursePerkPush() {
  const today = Utilities.formatDate(new Date(), CONFIG.TZ, 'yyyy-MM-dd'), props = PropertiesService.getScriptProperties();
  const v = studentSheet_().getDataRange().getValues(), miss = [];
  let n = 0;
  for (let i = 1; i < v.length; i++) {
    const d = v[i][2] instanceof Date ? Utilities.formatDate(v[i][2], CONFIG.TZ, 'yyyy-MM-dd') : String(v[i][2]);
    if (d !== today || v[i][7] === '已使用') continue;
    const code = String(v[i][6]).replace(/\D/g, ''), pk = 'perkpush_' + code;
    if (!code || props.getProperty(pk)) continue;
    const c = Object.keys(COURSES).map(function (k) { return COURSES[k]; }).filter(function (x) { return x.name === v[i][1]; })[0];
    if (!c || !c.perk) continue;
    const url = SITE_URL + '#/book/' + c.perk + '?c=' + code;
    const msg = v[i][3] + '，謝謝你今天來上「' + c.name + '」🌿\n\n送你一張【課後福利社】專屬預約：\n' + c.perkName + '\n學員價 NT$' + (c.perkPrice || 0) +
      '\n\n👉 點這裡選時間（學員密碼已經幫你帶好）：\n' + url + '\n\n有任何問題，直接回覆這則訊息就可以。';
    let ok = false; try { ok = linePushPhone_(phoneNorm_(v[i][4]), msg); } catch (e) {}
    if (ok) { props.setProperty(pk, today); n++; } else miss.push(v[i][3] + ' ' + phoneNorm_(v[i][4]));
  }
  if (miss.length) { try { linePushPhone_(OWNER_PHONE_, '🧾 課後福利社連結：' + n + ' 位已用 LINE 傳出。\n這幾位還沒綁官方 LINE，沒收到，請您私訊他們：\n' + miss.join('\n')); } catch (e) {} }
  return {sent: n, miss: miss};
}
